    43→function formatRelativeTime(isoString: string): string {
    44→  const diff = Date.now() - new Date(isoString).getTime();
    45→  const mins = Math.floor(diff / 60000);
    46→  if (mins < 60) return `${mins}m ago`;
    47→  const hrs = Math.floor(mins / 60);
    48→  if (hrs < 24) return `${hrs}h ago`;
    49→  return `${Math.floor(hrs / 24)}d ago`;
