    NavigationBar.setPositionAsync("relative").catch(() => {});
    NavigationBar.setBackgroundColorAsync(color).catch(() => {});
    NavigationBar.setButtonStyleAsync(isDark ? "light" : "dark").catch(() => {});
  }, [color, isDark]);
}

