     1→export interface UrlDisplayField {
     2→  label: string;
     3→  value: string;
     4→  icon: string;
     5→}
     6→
     7→export interface WebsiteData {
     8→  protocol: string;
     9→  isSecure: boolean;
    10→  hostname: string;
    11→  path: string;
    12→  hasQuery: boolean;
    13→  queryCount: number;
    14→  fullUrl: string;
    15→}
    16→
    17→export function parseWebsite(content: string): WebsiteData | null {
    18→  try {
    19→    const withScheme = content.startsWith("http") ? content : `https://${content}`;
    20→    const u = new URL(withScheme);
    21→    const isPrivate = /^(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(u.hostname);
    22→    const isGuard = u.pathname.startsWith("/guard/") || u.pathname.startsWith("/go/");
    23→    if (isPrivate || isGuard) return null;
    24→    const params = [...u.searchParams];
    25→    return {
    26→      protocol:   u.protocol.replace(":", "").toUpperCase(),
    27→      isSecure:   u.protocol === "https:",
    28→      hostname:   u.hostname.replace(/^www\./, ""),
    29→      path:       u.pathname !== "/" ? u.pathname : "",
    30→      hasQuery:   params.length > 0,
    31→      queryCount: params.length,
    32→      fullUrl:    content.startsWith("http") ? content : `https://${content}`,
    33→    };
    34→  } catch { return null; }
    35→}
    36→
    37→export function extractSocialFields(contentType: string, content: string): UrlDisplayField[] {
    38→  const fields: UrlDisplayField[] = [];
    39→  try {
    40→    switch (contentType) {
    41→      case "instagram": {
    42→        const m = content.match(/instagram\.com\/([^/?#\s]+)/);
    43→        if (m?.[1] && m[1] !== "p" && m[1] !== "reel")
    44→          fields.push({ label: "Profile", value: `@${m[1]}`, icon: "person-outline" });
    45→        break;
    46→      }
    47→      case "twitter": {
    48→        const m = content.match(/(?:twitter|x)\.com\/([^/?#\s]+)/);
    49→        if (m?.[1] && !["i", "intent", "home", "explore"].includes(m[1]))
    50→          fields.push({ label: "Username", value: `@${m[1]}`, icon: "person-outline" });
    51→        break;
    52→      }
    53→      case "tiktok": {
    54→        const m = content.match(/tiktok\.com\/@([^/?#\s]+)/);
    55→        if (m?.[1]) fields.push({ label: "Username", value: `@${m[1]}`, icon: "person-outline" });
    56→        break;
    57→      }
    58→      case "snapchat": {
    59→        const m = content.match(/snapchat\.com\/add\/([^/?#\s]+)/);
    60→        if (m?.[1]) fields.push({ label: "Username", value: m[1], icon: "person-outline" });
    61→        break;
    62→      }
    63→      case "youtube": {
    64→        const channel = content.match(/youtube\.com\/@([^/?#\s]+)/)?.[1]
    65→          ?? content.match(/youtube\.com\/channel\/([^/?#\s]+)/)?.[1]
    66→          ?? content.match(/youtube\.com\/c\/([^/?#\s]+)/)?.[1];
    67→        const video = content.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/)([^&/?#\s]+)/)?.[1];
    68→        if (channel) fields.push({ label: "Channel", value: `@${channel}`, icon: "play-circle-outline" });
    69→        if (video)   fields.push({ label: "Video ID", value: video, icon: "play-outline" });
    70→        break;
    71→      }
    72→      case "spotify": {
    73→        const track    = content.match(/spotify\.com\/track\/([^/?#\s]+)/)?.[1];
    74→        const album    = content.match(/spotify\.com\/album\/([^/?#\s]+)/)?.[1];
    75→        const playlist = content.match(/spotify\.com\/playlist\/([^/?#\s]+)/)?.[1];
    76→        const artist   = content.match(/spotify\.com\/artist\/([^/?#\s]+)/)?.[1];
    77→        if (track)         fields.push({ label: "Track", value: track, icon: "musical-note-outline" });
    78→        else if (album)    fields.push({ label: "Album", value: album, icon: "disc-outline" });
    79→        else if (playlist) fields.push({ label: "Playlist", value: playlist, icon: "musical-notes-outline" });
    80→        else if (artist)   fields.push({ label: "Artist", value: artist, icon: "person-outline" });
    81→        break;
    82→      }
    83→      case "linkedin": {
    84→        const m = content.match(/linkedin\.com\/(?:in|company|school)\/([^/?#\s]+)/);
    85→        if (m?.[1]) fields.push({ label: "Profile", value: m[1], icon: "person-outline" });
    86→        break;
    87→      }
    88→      case "telegram": {
    89→        const m = content.match(/t\.me\/([^/?#\s]+)/);
    90→        if (m?.[1]) fields.push({ label: "Username", value: `@${m[1]}`, icon: "paper-plane-outline" });
    91→        break;
    92→      }
    93→      case "discord": {
    94→        const m = content.match(/discord\.(?:gg|com\/invite)\/([^/?#\s]+)/);
    95→        if (m?.[1]) fields.push({ label: "Invite", value: m[1], icon: "link-outline" });
    96→        break;
    97→      }
    98→      case "facebook": {
    99→        const u = new URL(content.startsWith("http") ? content : `https://${content}`);
   100→        const path = u.pathname.replace(/^\/|\/$/g, "");
   101→        if (path && !["pages", "groups", "events", "login"].includes(path.split("/")[0]))
   102→          fields.push({ label: "Page", value: path, icon: "person-outline" });
   103→        break;
   104→      }
   105→      case "paypal": {
   106→        const username = content.match(/paypal\.me\/([^/?#\s/]+)/)?.[1];
   107→        const amount   = content.match(/paypal\.me\/[^/]+\/([^/?#\s]+)/)?.[1];
   108→        if (username) fields.push({ label: "Username", value: username, icon: "person-outline" });
   109→        if (amount)   fields.push({ label: "Amount", value: amount, icon: "cash-outline" });
   110→        break;
   111→      }
   112→      case "venmo": {
   113→        const u = new URL(content.startsWith("http") ? content : `https://${content}`);
   114→        const username = u.pathname.replace(/^\/@?|\/$/g, "") || u.searchParams.get("user") || "";
   115→        const amount   = u.searchParams.get("amount") ?? "";
   116→        const note     = u.searchParams.get("note") ?? "";
   117→        if (username) fields.push({ label: "Username", value: `@${username}`, icon: "person-outline" });
   118→        if (amount)   fields.push({ label: "Amount", value: amount, icon: "cash-outline" });
   119→        if (note)     fields.push({ label: "Note", value: note, icon: "document-text-outline" });
   120→        break;
   121→      }
   122→      case "zoom": {
   123→        const meetingId = content.includes("zoom.us/j/") ? content.split("/j/")[1]?.split("?")[0] ?? "" : "";
   124→        let pwd = "";
   125→        try { pwd = new URL(content).searchParams.get("pwd") ?? ""; } catch {}
   126→        if (meetingId) fields.push({ label: "Meeting ID", value: meetingId, icon: "videocam-outline" });
   127→        if (pwd)       fields.push({ label: "Passcode", value: pwd, icon: "key-outline" });
   128→        break;
   129→      }
   130→      case "calendly": {
   131→        const u = new URL(content.startsWith("http") ? content : `https://${content}`);
   132→        const parts = u.pathname.replace(/^\/|\/$/g, "").split("/").filter(Boolean);
   133→        if (parts[0]) fields.push({ label: "Username", value: parts[0], icon: "person-outline" });
   134→        if (parts[1]) fields.push({ label: "Event", value: parts[1].replace(/-/g, " "), icon: "calendar-outline" });
   135→        break;
   136→      }
   137→      case "razorpay":
   138→      case "donation":
   139→      case "reviewpage":
   140→      case "menucatalogue": {
   141→        const u = new URL(content.startsWith("http") ? content : `https://${content}`);
   142→        fields.push({ label: "Link", value: u.hostname.replace(/^www\./, "") + u.pathname.replace(/\/$/, ""), icon: "link-outline" });
   143→        break;
   144→      }
   145→      case "appdownload":
   146→      case "app": {
   147→        const isApple = content.includes("apps.apple.com");
   148→        fields.push({ label: "Store", value: isApple ? "App Store" : "Google Play", icon: "download-outline" });
   149→        try {
   150→          const u = new URL(content.startsWith("http") ? content : `https://${content}`);
   151→          const appName = u.pathname.split("/").filter(Boolean).pop()?.replace(/-/g, " ") || "";
   152→          if (appName) fields.push({ label: "App", value: appName, icon: "apps-outline" });
   153→        } catch {}
   154→        break;
   155→      }
   156→      default:
   157→        break;
   158→    }
   159→  } catch {}
   160→  return fields;
   161→}
   162→
   163→export function extractBasicPaymentInfo(content: string) {
   164→  try {
   165→    return {
   166→      vpa:      content.match(/pa=([^&\s]+)/i)?.[1] ? decodeURIComponent(content.match(/pa=([^&\s]+)/i)![1]) : undefined,
   167→      name:     content.match(/pn=([^&\s]+)/i)?.[1] ? decodeURIComponent(content.match(/pn=([^&\s]+)/i)![1]) : undefined,
   168→      amount:   content.match(/(?:\bam|amount)=([^&\s]+)/i)?.[1] ? decodeURIComponent(content.match(/(?:\bam|amount)=([^&\s]+)/i)![1]) : undefined,
   169→      currency: content.match(/cu=([^&\s]+)/i)?.[1] ? decodeURIComponent(content.match(/cu=([^&\s]+)/i)![1]) : undefined,
   170→    };
   171→  } catch { return {}; }
   172→}
