   138→  const handleScanWithCount = useCallback(async (data: any) => {
   139→    handleBarCodeScanned(data);
   140→    try {
   141→      const dismissed = await AsyncStorage.getItem(DONATION_DISMISS_KEY);
   142→      if (dismissed) return;
   143→      const stored   = await AsyncStorage.getItem(SCAN_COUNT_KEY);
   144→      const newCount = parseInt(stored || "0", 10) + 1;
   145→      await AsyncStorage.setItem(SCAN_COUNT_KEY, String(newCount));
   146→      if (newCount >= 5) setShowDonationBanner(true);
   147→    } catch {}
   148→  }, [handleBarCodeScanned]);
   149→
   150→  // ── Permission not yet resolved ────────────────────────────────────────────
   151→  if (!permission) {
   152→    return <View style={{ flex: 1, backgroundColor: "#000" }} />;
   153→  }
   154→
   155→  // ── Permission denied ─────────────────────────────────────────────────────
   156→  if (!permission.granted) {
   157→    return (
   158→      <View style={{ flex: 1, backgroundColor: colors.background }}>
   159→        <StatusBar style={colors.isDark ? "light" : "dark"} />
   160→        <PermissionScreen
   161→          canAskAgain={permission.canAskAgain}
   162→          onRequestPermission={requestPermission}
   163→        />
   164→        {scannerMsg && (
   165→          <View style={[toastContainerStyle, { bottom: 32 }]}>
   166→            <ScannerToast message={scannerMsg} type={scannerMsgType} onDone={dismissScannerMsg} />
   167→          </View>
   168→        )}
   169→      </View>
   170→    );
   171→  }
   172→
   173→  // ── Main render ───────────────────────────────────────────────────────────
   174→  return (
   175→    <View style={{ flex: 1, backgroundColor: "#000" }}>
   176→      <StatusBar style="light" backgroundColor="transparent" translucent />
   177→
   178→      {/* Camera / hardware guard */}
   179→      {hardwareAvailable === null ? (
   180→        <View style={[StyleSheet.absoluteFillObject, { backgroundColor: "#000" }]} />
   181→      ) : hardwareAvailable === false || !cameraAvailable ? (
   182→        <View style={[StyleSheet.absoluteFillObject, { backgroundColor: "#080c14" }]}>
   183→          <View style={{ paddingTop: topInset + 8, paddingHorizontal: 16, paddingBottom: 10 }}>
   184→            <Pressable onPress={() => router.back()} style={styles.backBtn}>
   185→              <Ionicons name="chevron-back" size={22} color="#fff" />
   186→            </Pressable>
   187→          </View>
   188→          <View style={{ flex: 1, justifyContent: "center", alignItems: "center" }}>
   189→            <CameraUnavailableBanner onPickImage={handlePickImage} errorType={cameraErrorType} />
   190→          </View>
   191→        </View>
   192→      ) : (
   193→        <CameraErrorBoundary onError={() => markCameraUnavailable("unavailable")}>
   194→          <CameraView
   195→            style={StyleSheet.absoluteFillObject}
   196→            facing={facing}
   197→            enableTorch={flashOn && facing === "back"}
   198→            zoom={zoom}
   199→            barcodeScannerSettings={{ barcodeTypes: ["qr"] }}
   200→            onBarcodeScanned={scanned ? undefined : handleScanWithCount}
   201→            onCameraReady={markCameraReady}
   202→            onMountError={(error) => {
   203→              const msg     = (error?.message ?? "").toLowerCase();
   204→              const isInUse =
   205→                msg.includes("in use")     ||
   206→                msg.includes("busy")       ||
   207→                msg.includes("already")    ||
   208→                msg.includes("another app")||
   209→                msg.includes("restricted");
   210→              markCameraUnavailable(isInUse ? "inuse" : "unavailable");
   211→            }}
   212→          />
   213→        </CameraErrorBoundary>
   214→      )}
   215→
   216→      {/* Scanner overlay (controls, finder, animations) */}
   217→      {hardwareAvailable === true && cameraAvailable && (
   218→        <ScannerOverlay
   219→          topInset={topInset}
   220→          bottomInset={bottomInset}
   221→          flashOn={flashOn}
   222→          onToggleFlash={() => setFlashOn(!flashOn)}
   223→          zoom={zoom}
   224→          zoomLabel={zoomLabel}
   225→          onCycleZoom={cycleZoom}
   226→          scanned={scanned}
   227→          scanSuccess={scanSuccess}
   228→          scanLineAnim={scanLineAnim}
   229→          anonymousMode={anonymousMode}
   230→          onToggleAnonymous={() => setAnonymousMode(!anonymousMode)}
   231→          onPickImage={handlePickImage}
   232→          onReset={resetScan}
   233→          user={user}
   234→          facing={facing}
   235→          onFlipCamera={flipCamera}
   236→        />
   237→      )}
   238→
   239→      {/* Modals & overlays */}
