   162→  // ─── Background Firestore sync (fire-and-forget) ──────────────────────────────
   163→  function _backgroundSync(
   164→    content:     string,
   165→    localQrId:   string,
   166→    contentType: string,
   167→    scanSource:  "camera" | "gallery"
   168→  ) {
   169→    (async () => {
   170→      try {
   171→        const qr = await getOrCreateQrCode(content);
   172→        await AsyncStorage.setItem(
   173→          `qr_content_${qr.id}`,
   174→          JSON.stringify({ content: qr.content, contentType: qr.contentType })
   175→        ).catch(() => {});
   176→        if (user?.id) {
   177→          recordScan(qr.id, content, qr.contentType, user.id, false, scanSource).catch(() => {});
   178→          await appendToLocalScanHistory(
   179→            user.id,
   180→            makeScanEntry(content, qr.contentType, qr.id, scanSource)
   181→          );
   182→        }
   183→      } catch {}
   184→    })();
   185→  }
   186→
   187→  // ─── Main scan path ───────────────────────────────────────────────────────────
   188→  async function processScan(content: string, scanSource: "camera" | "gallery" = "camera") {
   189→    const routeGuard = async (uuid: string, param: string) => {
   190→      setProcessing(false);
   191→      setScanSuccess(true);
   192→      const isGuard = param === "guardUuid";
   193→      showScannerMsg(
   194→        isGuard ? "Living Shield QR detected" : "QR Guard standard code detected",
   195→        "info"
   196→      );
   197→      const qrId = await getQrCodeId(content);
   198→      router.push(`/qr-detail/${qrId}?${param}=${uuid}`);
   199→    };
   200→
   201→    const guardMatch    = content.match(GUARD_PATTERN);
   202→    const standardMatch = content.match(STANDARD_PATTERN);
   203→
   204→    if (user && anonymousMode) {
   205→      if (guardMatch)    { await routeGuard(guardMatch[1].toUpperCase(),    "guardUuid");    return; }
   206→      if (standardMatch) { await routeGuard(standardMatch[1].toUpperCase(), "standardUuid"); return; }
   207→      await processScanAnonymous(content);
   208→      return;
   209→    }
   210→
   211→    if (guardMatch)    { await routeGuard(guardMatch[1].toUpperCase(),    "guardUuid");    return; }
   212→    if (standardMatch) { await routeGuard(standardMatch[1].toUpperCase(), "standardUuid"); return; }
   213→
   214→    setProcessing(true);
   215→    try {
   216→      const validation = validateQrInput(content);
   217→      if (!validation.valid) {
   218→        setProcessing(false);
   219→        showScannerMsg(validation.error || "Invalid QR code content", "error");
   220→        Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error);
   221→        return;
   222→      }
   223→
   224→      const qrId        = await getQrCodeId(content);
   225→      const contentType = detectContentType(content);
   226→
   227→      await AsyncStorage.setItem(
   228→        `qr_content_${qrId}`,
   229→        JSON.stringify({ content, contentType })
   230→      ).catch(() => {});
   231→
   232→      setProcessing(false);
   233→
   234→      if (contentType === "url") {
   235→        const check = runSecurityCheck(content);
   236→        if (check.hasThreat) {
   237→          modalControls.openSafetyModal(qrId, check.warnings, check.riskLevel);
   238→          Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
   239→          _backgroundSync(content, qrId, contentType, scanSource);
   240→          return;
   241→        }
   242→      }
   243→
   244→      navigateToQrDetail(qrId);
   245→      _backgroundSync(content, qrId, contentType, scanSource);
   246→    } catch {
   247→      await processOfflineScan(content, scanSource);
   248→    }
   249→  }
   250→
   251→  // ─── Public handlers ──────────────────────────────────────────────────────────
   252→  const handleBarCodeScanned = useCallback(
   253→    async ({ data }: { data: string }) => {
   254→      if (!canScanRef.current || scanLockRef.current || scanned) return;
   255→      scanLockRef.current = true;
   256→      canScanRef.current  = false;
   257→      setScanned(true);
   258→      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
   259→      await processScan(data, "camera");
   260→    },
   261→    [scanned, anonymousMode, user, token]
   262→  );
   263→
   264→  async function handlePickImage() {
   265→    if (!token) {
   266→      showScannerMsg("Sign in to scan QR codes from your gallery.", "info");
   267→      return;
   268→    }
   269→
   270→    let result: ImagePicker.ImagePickerResult;
   271→    try {
   272→      result = await ImagePicker.launchImageLibraryAsync({
   273→        mediaTypes:              ["images"],
   274→        allowsEditing:           false,
   275→        allowsMultipleSelection: false,
   276→        exif:                    false,
   277→      });
   278→    } catch {
   279→      showGalleryError("Could not open your gallery. Please try again.");
   280→      return;
   281→    }
   282→
   283→    if (result.canceled || !result.assets?.[0]) return;
   284→
   285→    setProcessing(true);
   286→    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   287→
   288→    try {
   289→      const uri     = result.assets[0].uri;
   290→      let content: string | null = null;
   291→
   292→      if (Platform.OS === "web") {
   293→        content = await decodeQrFromImageUri(uri);
   294→      } else {
   295→        const results = await scanFromURLAsync(uri, ["qr"]);
   296→        content = results?.[0]?.data ?? null;
   297→      }
   298→
   299→      if (!content) {
   300→        showGalleryError("No QR code found in this image — try a clearer or closer photo.");
   301→        setProcessing(false);
   302→        return;
   303→      }
   304→
   305→      await processScan(content, "gallery");
   306→    } catch (e: any) {
   307→      setProcessing(false);
   308→      showGalleryError(e.message || "Something went wrong. Please try again.");
   309→    }
   310→  }
   311→
   312→  return { handleBarCodeScanned, handlePickImage };
   313→}
