    14→
    15→export const ZOOM_LEVELS = [
    16→  { zoom: 0,   label: "1×" },
    17→  { zoom: 0.3, label: "2×" },
    18→  { zoom: 0.6, label: "3×" },
    19→];
    20→
    21→// Auto-zoom stages: after N ms without a scan, try a different zoom level
    22→const AUTO_ZOOM_STAGES = [
    23→  { delay: 4000,  zoom: 0.18, label: "1.5×" },
    24→  { delay: 8000,  zoom: 0.42, label: "2×"   },
    25→  { delay: 12000, zoom: 0,    label: "1×"    }, // reset
    26→];
    27→
    28→export function useCameraControls() {
    29→  const [scanned, setScanned]         = useState(false);
    30→  const [processing, setProcessing]   = useState(false);
    31→  const [scanSuccess, setScanSuccess] = useState(false);
    32→  const [flashOn, setFlashOn]         = useState(false);
    33→  const [zoom, setZoom]               = useState(0);
    34→  const [zoomLabel, setZoomLabel]     = useState("1×");
    35→
    36→  const scanLockRef  = useRef(false);
    37→  const canScanRef   = useRef(false);
    38→  const focusTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    39→
    40→  // Auto-zoom state
    41→  const autoZoomTimers = useRef<ReturnType<typeof setTimeout>[]>([]);
    42→  const manualZoomRef  = useRef(false); // user manually cycled zoom
    43→
    44→  const scanLineAnim = useRef(new Animated.Value(0)).current;
    45→  const scanLineLoop = useRef<Animated.CompositeAnimation | null>(null);
    46→
    47→  function startScanLine() {
    48→    scanLineAnim.setValue(0);
    49→    scanLineLoop.current = Animated.loop(
    50→      Animated.sequence([
    51→        Animated.timing(scanLineAnim, {
    52→          toValue: 1, duration: 2000,
    53→          easing: Easing.inOut(Easing.ease), useNativeDriver: true,
    54→        }),
    55→        Animated.timing(scanLineAnim, {
    56→          toValue: 0, duration: 2000,
    57→          easing: Easing.inOut(Easing.ease), useNativeDriver: true,
    58→        }),
    59→      ])
    60→    );
    61→    scanLineLoop.current.start();
    62→  }
    63→
    64→  function stopScanLine() {
    65→    if (scanLineLoop.current) scanLineLoop.current.stop();
    66→  }
    67→
    68→  function clearAutoZoomTimers() {
    69→    autoZoomTimers.current.forEach(clearTimeout);
    70→    autoZoomTimers.current = [];
    71→  }
    72→
    73→  function startAutoZoom() {
    74→    clearAutoZoomTimers();
    75→    manualZoomRef.current = false;
    76→    AUTO_ZOOM_STAGES.forEach(({ delay, zoom: z, label }) => {
    77→      const t = setTimeout(() => {
    78→        // Only auto-zoom if user hasn't manually overridden
    79→        if (!manualZoomRef.current) {
    80→          setZoom(z);
    81→          setZoomLabel(label);
    82→        }
    83→      }, delay);
    84→      autoZoomTimers.current.push(t);
    85→    });
    86→  }
