    88→  function resetAutoZoom() {
    89→    clearAutoZoomTimers();
    90→    setZoom(0);
    91→    setZoomLabel("1×");
    92→    manualZoomRef.current = false;
    93→  }
    94→
    95→  useEffect(() => {
    96→    startScanLine();
    97→    startAutoZoom();
    98→    return () => {
    99→      stopScanLine();
   100→      clearAutoZoomTimers();
   101→    };
   102→  }, []);
   103→
   104→  useFocusEffect(
