   106→      setScanned(false);
   107→      setProcessing(false);
   108→      setScanSuccess(false);
   109→      scanLockRef.current = false;
   110→      canScanRef.current = false;
   111→      startScanLine();
   112→      startAutoZoom();
   113→      focusTimerRef.current = setTimeout(() => {
   114→        canScanRef.current = true;
   115→      }, 200);
   116→      return () => {
   117→        if (focusTimerRef.current) clearTimeout(focusTimerRef.current);
   118→        canScanRef.current = false;
   119→        stopScanLine();
   120→        clearAutoZoomTimers();
   121→      };
   122→    }, [])
   123→  );
   124→
   125→  function resetScan() {
   126→    setScanned(false);
   127→    setScanSuccess(false);
   128→    setProcessing(false);
   129→    scanLockRef.current = false;
   130→    canScanRef.current = true;
   131→    resetAutoZoom();
   132→    startAutoZoom();
   133→  }
