   143→  }
   144→
   145→  return {
   146→    scanned, setScanned,
   147→    processing, setProcessing,
   148→    scanSuccess, setScanSuccess,
   149→    flashOn, setFlashOn,
   150→    zoom, zoomLabel,
   151→    scanLineAnim,
   152→    scanLockRef, canScanRef,
   153→    resetScan,
   154→    cycleZoom,
   155→  };
