import re, os

# Comprehensive fix for all remaining animation issues
fixes = {
    # (file, old_pattern, new_text)
}

# Files to fix with delay compression
delay_map = {
    500: 260, 400: 80, 360: 80, 350: 260, 300: 80,
    280: 80, 260: 80, 240: 80, 220: 70, 200: 70,
    190: 60, 180: 60, 160: 50, 140: 50, 130: 50,
    120: 50, 110: 50, 100: 50, 80: 40, 60: 30,
}

# Duration fixes (duration values that are too slow)
duration_map = {
    500: 260, 400: 260, 360: 260, 350: 260,
    320: 260, 300: 260,
}

target_files = [
    'features/qr-detail/components/TrustScoreCard.tsx',
    'features/qr-detail/content-cards/cards/WebsiteCard.tsx',
    'features/home/components/HomeHeader.tsx',
    'features/home/components/RecentScanCard.tsx', 
    'features/home/components/ScanSkeletonList.tsx',
    'features/generator/components/EmptyQrPlaceholder.tsx',
    'features/generator/components/TemplateReadyCard.tsx',
    'features/generator/components/builder/OutputView.tsx',
    'features/scanner/components/overlay/ScannerOverlay.tsx',
]

def compress_delay(m):
    n = int(m.group(1))
    new = delay_map.get(n)
    if new is not None:
        return f'.delay({new})'
    return m.group(0)

def compress_duration(m):
    n = int(m.group(1))
    new = duration_map.get(n)
    if new is not None:
        return f'.duration({new})'
    return m.group(0)

for path in target_files:
    if not os.path.exists(path):
        print(f'SKIP {path}'); continue
    with open(path, 'r') as f:
        content = f.read()
    new_content = re.sub(r'\.delay\((\d+)\)', compress_delay, content)
    new_content = re.sub(r'\.duration\((\d+)\)', compress_duration, new_content)
    # Also fix duration(N) that comes before .delay (alternate order)
    if new_content != content:
        with open(path, 'w') as f:
            f.write(new_content)
        print(f'FIXED {path}')
    else:
        print(f'UNCHANGED {path}')

